(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.32)*12;
  const sx1 = x+w1x, sy1 = y+w1y;
  const w2x = Math.sin(sx1*0.025-t*0.4)*8 + Math.cos(sy1*0.02+t*0.35)*6;
  const w2y = Math.cos(sy1*0.022+t*0.38)*8 + Math.sin(sx1*0.019-t*0.42)*6;
  const sx = sx1+w2x, sy = sy1+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+2)*65, 0.11, 2.1, 1.0],
    [400+Math.cos(t*0.55+1)*85, 200+Math.sin(t*0.75+4)*55, 0.065, 2.4, 0.88],
    [200+Math.sin(t*0.25+6)*130, 220+Math.cos(t*0.45+3)*70, 0.095, 1.8, 1.08]
  ];
  let aS = 0, iS = 0, harm = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    harm += Math.sin(d*f*1.3 - t*sp*0.8 + 0.7) * w * 0.4;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, hrm = harm/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = Math.sin(dist*0.03+ang*6-t*0.8)*Math.cos(dist*0.07-ang*2+t*1.3)*0.2;
  const moire = Math.sin(sx*0.22)*Math.sin(sy*0.22) + Math.sin((sx-sy)*0.18+t*0.7)*0.5;
  const voronoi = (() => {
    let md = 1e9, md2 = 1e9;
    for (let i = 0; i < n; i += 2) {
      const vx = src[i][0] + Math.sin(t*0.5+i)*20, vy = src[i][1] + Math.cos(t*0.4+i)*20;
      const d = Math.sqrt((sx-vx)**2 + (sy-vy)**2);
      if (d < md) { md2 = md; md = d; } else if (d < md2) { md2 = d; }
    }
    return Math.sin((md2-md)*0.5)*0.3;
  })();
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + spiral2 + hrm*0.3)*2.0);
  const cell = Math.tanh((moire + voronoi)*1.2)*0.25;
  const pulse = Math.sin(t*0.4)*0.08;
  const blend = reaction*0.7 + cell*0.3 + pulse;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,45,85],[18,90,115],[28,140,135],[65,175,140],
    [160,195,100],[210,185,65],[220,140,60],[195,90,65],[150,55,70],
    [90,30,65],[40,15,55],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85 + Math.sin(reaction*Math.PI)*0.15;
  const edge = Math.abs(reaction)>0.65 ? 1.12 + Math.abs(reaction)*0.08 : 1.0;
  const glow = Math.max(0, reaction-0.3)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*80)|0)
  ];
}
